{
  "query": "How do I run a voice model on nearby GPUs instead of sending every request to a central server?",
  "summary": "You can run speech models (ASR such as Whisper, TTS such as Piper or XTTS) on GPUs near the user, either on your own LAN or across a decentralized GPU marketplace. The main work is packaging the model as a stateless worker, discovering nodes, routing each request to the closest healthy one, and falling back to a central server when needed. Latency is the main constraint for voice, so the design should favor nodes that are one network hop away.",
  "architecture": {
    "components": [
      {
        "name": "Model workers",
        "description": "Run speech models on each GPU node, for example faster-whisper or whisper.cpp for speech-to-text and Piper or Coqui XTTS-v2 for text-to-speech. Expose them through a small streaming API (FastAPI or gRPC) that accepts audio chunks and returns partial transcripts or audio frames."
      },
      {
        "name": "Discovery",
        "description": "On a LAN, use mDNS/DNS-SD or libp2p for peer discovery. Across the internet, use a DHT such as libp2p Kademlia, or a registry that nodes announce to. Keep a heartbeat with each node's model list, GPU load, and measured RTT."
      },
      {
        "name": "Routing",
        "description": "The client picks the lowest-latency node that has the required model loaded and spare capacity. Keep a warm connection open, for example WebSocket or WebRTC, and stream audio in roughly 200 to 500 ms chunks rather than sending whole utterances."
      },
      {
        "name": "Fallback",
        "description": "If no nearby node responds within a latency budget, such as 150 to 300 ms for the first chunk, route to the central server. This keeps availability high while you learn how the edge nodes behave."
      },
      {
        "name": "Trust and payment (optional)",
        "description": "If strangers run your nodes, you need output verification, reputation, and payment. Marketplaces handle this for you; see the platforms below."
      }
    ]
  },
  "steps": [
    "1. Benchmark the model on your target GPUs (for example, RTX 3060 or T4 class) and record real-time factor and first-chunk latency.",
    "2. Wrap the model in a container with a streaming endpoint and a /health route that reports loaded models and queue depth.",
    "3. Deploy workers on the nearby machines, for example through Docker or Nomad, and register them with your discovery layer.",
    "4. Build a client SDK that pings candidate nodes, selects the fastest, and opens a streaming session.",
    "5. Add a central fallback and set timeouts so a slow edge node never blocks a conversation.",
    "6. Measure end-to-end latency and failure rates, then tune chunk size and node selection."
  ],
  "platforms": [
    {
      "name": "Akash Network",
      "type": "Decentralized cloud (Cosmos-based, AKT)",
      "fit": "Deploy containerized GPU workloads on a provider you choose by region and price. Good for hosting a model worker in a specific geography."
    },
    {
      "name": "io.net",
      "type": "GPU aggregator (Solana-based, IO)",
      "fit": "Aggregates GPUs from many suppliers for inference and training. Useful when you want capacity close to your users without running hardware yourself."
    },
    {
      "name": "Render Network",
      "type": "Distributed GPU rendering that has expanded into AI (RENDER)",
      "fit": "Mature GPU marketplace with a large node base, though it is more focused on rendering than low-latency streaming."
    },
    {
      "name": "Aethir",
      "type": "Decentralized GPU cloud with enterprise focus (ATH)",
      "fit": "Enterprise-oriented GPU capacity across many regions, suited to production inference contracts."
    },
    {
      "name": "Nosana",
      "type": "Decentralized compute on Solana (NOS)",
      "fit": "Job-based GPU execution, which works for batch transcription or model serving that can tolerate queueing."
    },
    {
      "name": "Bittensor",
      "type": "Incentivized machine-learning network (TAO)",
      "fit": "Subnets pay miners for useful model outputs. Useful if you want an incentive layer for model quality, but latency and control are less predictable than in a dedicated deployment."
    },
    {
      "name": "Gensyn",
      "type": "Verifiable ML compute protocol",
      "fit": "Focused on verifying that training and inference were performed correctly. Still early; better for trust-sensitive workloads than for voice latency today."
    },
    {
      "name": "Golem Network",
      "type": "Decentralized compute marketplace (GLM)",
      "fit": "General-purpose compute marketplace; less specialized for GPU inference than io.net or Aethir."
    }
  ],
  "competitors_and_alternatives": [
    "Central cloud GPU inference: AWS, Google Cloud, Azure, and speech APIs such as Deepgram, AssemblyAI, and ElevenLabs. These are simpler and more predictable on latency but send all traffic to a central region.",
    "Edge and local inference frameworks: Exo for splitting models across LAN devices, Ollama for local serving (LLMs rather than speech), and on-device runtimes such as Core ML or ONNX Runtime for running entirely on the user's device.",
    "Edge CDNs with GPU support: Cloudflare Workers AI and Fastly Compute offer regional inference without you managing nodes, though GPU options are limited compared with dedicated providers."
